# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe "Owner-aware time-tracking reads", type: :request do
  # "The entry list and read-after-write reads go to the current owner: Timekeeping, or the prepared
  # monolith's local tables, or `timesheet_entries` in the legacy state."
  # "Include a case where delivery is paused and a newly created entry still shows at once in the
  # time-tracking index and entry list."
  # The projection row below has no counterpart at the owner, as after an undelivered discard; a
  # reader that merges sources or falls back to timesheet_entries would show it.
  it "shows the owner's undelivered entry and never a projection-only row while Timekeeping owns entries" do
    company = create(:company)
    user = create(:user, current_workspace_id: company.id)
    create(:employment, company:, user:)
    user.add_role(:admin, company)
    project = create(:project, client: create(:client, company:))
    projection_only = create(:timesheet_entry, user:, project:, work_date: Date.new(2026, 3, 2), note: "projection only")
    projection_only.update_columns(company_id: company.id)

    fake_timekeeping = TimekeepingContract::FakeTimekeeping.new
    owner_entry = fake_timekeeping.add_entry(company_id: company.id, user_id: user.id, project_id: project.id,
                                             work_date: "2026-03-02", duration: 60.0, note: "owner only")
    allow(Timekeeping::EntryApiClient).to receive(:new)
      .and_return(TimekeepingContract::FakeEntryApiClient.new(timekeeping: fake_timekeeping))
    TimekeepingOwnership.current.update!(owner: "timekeeping", generation: 2, handoff_step: nil)
    sign_in user

    params = { from: "2026-03-01", to: "2026-03-31" }
    [api_v1_time_tracking_index_path, api_v1_timesheet_entry_index_path].each do |path|
      send_request :get, path, params:, headers: auth_headers(user)

      expect(response).to have_http_status(:ok)
      notes = json_response.fetch("entries").fetch("2026-03-02", []).pluck("note")
      expect([path, notes]).to eq([path, ["owner only"]])
    end
    expect(TimesheetEntry.where(id: owner_entry.fetch("id"))).not_to exist
  end

  it "answers both reads with a JSON 503 when Timekeeping owns entries and cannot be read" do
    company = create(:company)
    user = create(:user, current_workspace_id: company.id)
    create(:employment, company:, user:)
    user.add_role(:admin, company)
    TimekeepingOwnership.current.update!(owner: "timekeeping", generation: 2, handoff_step: nil)
    allow(Timekeeping::EntryApiClient).to receive(:new).and_return(Timekeeping::EntryApiClient.new(base_url: nil))
    sign_in user

    [api_v1_time_tracking_index_path, api_v1_timesheet_entry_index_path].each do |path|
      send_request :get, path, params: { from: "2026-03-01", to: "2026-03-31" }, headers: auth_headers(user)

      expect([path, response.status]).to eq([path, 503])
      expect(json_response).to eq("errors" => "TIMEKEEPING_BASE_URL is not set")
    end
  end
end
